# THE ACCENT CLASSES (M-26; measured on the DB's own code points at the sitting): the conjunctives join, every other accent is a disjunctive
_CONJ = {'\u05A3', '\u05A5', '\u05A4', '\u05A7', '\u05A8', '\u05A9', '\u05AA', '\u05A6'}   # munach, merkha, mahapakh, darga, qadma, telisha qetana, yerach ben yomo, merkha kefula
_DISJ = {chr(c) for c in range(0x0591, 0x05AF)} - _CONJ - {'\u05AF'}
