def _bare_ord(w):
    for p in ('', 'ה', 'ב', 'וב'):
        if w.startswith(p) and w[len(p):] in _ORD:
            return _ORD[w[len(p):]]
    return None


def verse_words(book, ch, vs):
    r = _con.cursor().execute("select id from verses where book=? and chapter=? and verse=?", (book, ch, vs)).fetchone()
    if r is None:
        raise SystemExit('INK: no verse %s %d:%d in the Tanakh DB' % (book, ch, vs))
    out = []
    raws = [w for (w,) in _con.cursor().execute("select he from words where verse_id=? order by idx", (r[0],))]
    for i, w in enumerate(raws):
        bare = re.sub(r'[֑-ׇ/]', '', w)
        # THE NUMBERS WALK 1b (2026-09-09; NUMBERS_WALK.md "Sitting 1b"): the consonantal homograph מאת — מְאַת ("a hundred of",
        # Num 2:9, Exod 38:25) against מֵאֵת ("from", Num 3:49-50, Gen 23:20) — told apart by the tsere under the mem; the
        # preposition is emitted as מ-את so the parser never reads it as a number (the pointed form is the DB's own)
        pw = re.sub(r'[\u0591-\u05AF/]', '', w)          # the points kept, the accents off
        # THE NUMBERS WALK 1b (2026-09-09; NUMBERS_WALK.md "Sitting 1b"): TWO HOMOGRAPHS TOLD APART BY THE POINTS ON THE STEM (measured on
        # the DB's own code points: the shin-dot follows the shin, then the vowel; a dagesh may sit before the vowel) —
        # (1) מאת: the tsere under the mem AND under the alef is 'from' (מֵאֵת, Num 3:49, Gen 23:20 — emitted מ-את, never a number);
        #     מְאַת ('a hundred of', Num 2:9) and מֵאֹת ('hundreds', Gen 5:4 — the plural's holam) stay numerals;
        # (2) שנים: a sheva under the shin and no hiriq under the nun is the numeral 'two' (שְׁנַיִם Num 3:39, שְׁנֵים 'twelve' Num 1:44,
        #     the pausal שְׁנָיִם Num 13:23); a qamats under the shin is 'years' (שָׁנִים Gen 5:6; וְשָׁנִים Gen 1:14; בַּשָּׁנִים Lev 25:51)
        #     and the hiriq under the nun 'second ones' (שְׁנִיִּם Gen 6:16) — the non-numeral is emitted with a star (שנים*) and the
        #     parser keeps the phrase open on it as on שנה
        if bare.endswith('מאת') and bare in ('מאת', 'ומאת'):
            st = pw[pw.rfind('מ'):].replace('\u05BC', '')
            if re.match(r'^מ\u05B5א\u05B5', st):
                bare = bare[:-3] + 'מ-את'
        if bare.endswith('שנים') and bare in ('שנים', 'ושנים', 'בשנים', 'לשנים', 'כשנים'):
            st = pw[pw.rfind('ש'):].replace('\u05C1', '').replace('\u05C2', '').replace('\u05BC', '')
            if not re.match(r'^ש\u05B0נ[^\u05B4]', st):
                bare = bare + '*'
        # THE NUMBERS WALK 2b (2026-09-10; NUMBERS_WALK.md "Sitting 2b"): (3) THE CONSTRUCT 'two of' BY THE POINTS ON THE STEM — שְׁנֵי / שְׁתֵּי (a sheva
        #     under the shin AND a tsere under the second letter; the morphology's HAcmdc / HAcfdc, Num 7:3, 7:7, 6:10) is emitted with a caret
        #     (שני^) so the numeral reader takes it as 2 and the ordinal reader keeps שֵׁנִי 'second' (a tsere under the shin — 6:10's 'two young
        #     pigeons' had read as the ORDINAL 2); שָׁנִי 'scarlet', שְׁנִי 'scarlet of' (a hiriq under the nun, Lev 14:4), שִׁנֵּי 'the teeth of',
        #     שְׁתִי 'the warp' (Lev 13) and Vashti stay words
        if bare in ('שני', 'ושני', 'בשני', 'לשני', 'משני', 'כשני', 'שתי', 'ושתי', 'בשתי', 'לשתי', 'משתי', 'כשתי'):
            st = pw[pw.rfind('ש'):].replace('\u05C1', '').replace('\u05C2', '').replace('\u05BC', '')
            if re.match(r'^ש\u05B0[נת]\u05B5', st):
                # THE HOMOGRAPH THE POINTS CANNOT SPLIT (measured at the sitting): שְׁנֵי 'two of' and שְׁנֵי 'THE YEARS OF' (Gen 47:28 'the years of
                # his life', 41:47 'the years of plenty', Exod 6:16, Lev 25:15 'the years of produce') carry the same points AND the same
                # morphology tag (HAcmdc, the tagger's own miss) — the neighbors decide: after יְמֵי 'the days of', or before a life / plenty /
                # famine / sojourn / produce / sale / hire word, it is the year-word (starred: it keeps a phrase open like שנים*), else the numeral
                pb = re.sub(r'[֑-ׇ/]', '', raws[i - 1]) if i > 0 else ''
                nb2 = re.sub(r'[֑-ׇ/]', '', raws[i + 1]) if i + 1 < len(raws) else ''
                if pb == 'ימי' or nb2.startswith(('חיי', 'השבע', 'רעב', 'הרעב', 'מגורי', 'תבואת', 'ממכרו', 'שכיר')):
                    bare = bare + '*'
                else:
                    bare = bare + '^'
        # (4) M-26 THE ACCENT READ — 'one' (אחד / אחת, with or without the vav) carrying a DISJUNCTIVE accent and followed by a numeral word
        #     WITHOUT the conjunction ENDS its number (emitted with a bar; ink_numbers closes the phrase after it): Num 7:13 'one [dish], a hundred
        #     and thirty' (a revia), 7:14 'one [pan], ten' (a tevir), 28:27 'one ram, seven lambs' (an etnachta); a conjunctive, a maqqef or no
        #     accent joins — every true eleven (Gen 32:23 a merkha, Deut 1:2 a qadma, 2 Kgs 9:29 a munach, Josh 15:51 the maqqef). Measured on
        #     the four books before the rule: of 325 numeral pairs without the conjunction, the 'one' seats alone move (twenty-five verses)
        if bare in ('אחד', 'אחת', 'ואחד', 'ואחת', 'שתים', 'ושתים', 'שנים', 'ושנים') and i + 1 < len(raws) and '\u05BE' not in w:   # 'two' too: Lev 23:17 'two [loaves], two tenths' (a yetiv on the first) — every 'twelve' joins by a conjunctive or the maqqef (measured)
            nb = re.sub(r'[֑-ׇ/]', '', raws[i + 1])
            if not nb.startswith('ו') and (_bare(nb) is not None or nb.lstrip('ובלמכ') in ('שני', 'שתי')) and any(c in _DISJ for c in w):   # the next word's caret is not yet on it: the construct counted here
                bare = bare + '|'
        # THE NUMBERS WALK 9b (2026-09-11; NUMBERS_WALK.md "Sitting 9b"): (25) THE DISJUNCTIVE ON A UNIT BEFORE "AND" + A UNIT — M-26 at the CONJOINED
        #     case: a unit numeral (one to nine) carrying a disjunctive accent before 'and' + a unit numeral ENDS its number (Num 28:19 'and one ram, |
        #     and seven lambs' and Exod 36:10 'one to one, | and five curtains' — both under the etnachta, both read joined since the parser's first day);
        #     the join under a CONJUNCTIVE is kept (Gen 8:13 'in the ONE and six hundredth year' — a qadma: 601, the unit multiplying the hundreds — the
        #     seat that refuses the accent-free form). Measured on the whole Tanakh: twenty-three seats of a unit before 'and' + a unit; in the four books
        #     the two cuts alone carry a disjunctive, every compound 'one and N' a conjunctive. The definite one keeps rule (18)'s own path below.
        if not bare.endswith(('|', '*', '#', '^', '~', '%', '@')) and not bare.startswith(('ה', 'וה')) and i + 1 < len(raws) and '־' not in w:
            cu = _bare(bare)
            if cu is not None and 1 <= UNITS.get(cu, 0) <= 9:
                nb = re.sub(r'[֑-ׇ/]', '', raws[i + 1])
                if nb.startswith('ו') and not nb.startswith('וה') and 1 <= UNITS.get(nb[1:], 0) <= 9 and any(c in _DISJ for c in w):
                    bare = bare + '|'
        # THE NUMBERS WALK 3b (2026-09-10): THE SEVEN-STEM'S HOMOGRAPHS, surfaced by the sitting's corpus-wide diff and told apart BY THE POINTS ON THE
        # STEM and by a neighbor (the 1b law): (8) the SIN dot on the shin is 'sated / plenty' (שָׂבָע Gen 41:29, וְשָׂבֵעַ 25:8, לָשֹׂבַע Lev 25:19 — eighteen
        # seats had read as seven); (9) a QUBUTS under the vet is 'oath / week' (שְׁבֻעַת Exod 22:10, Num 5:21; שָׁבֻעֹת 'weeks' Deut 16:9, Exod 34:22;
        # שְׁבֻעַ 'week' Gen 29:27-28); (10) a HIRIQ under the vet is the ordinal 'seventh' (שְּׁבִעִת Exod 21:2); (11) 'שבע' after 'באר' is BEER-SHEBA
        # (ten seats), and 'שבעה' named by 'he called it' is Shibah (Gen 26:33) — the name class, Kiriath-arba's precedent. Each is emitted with a
        # star (a word, never a numeral); the conjunction's shureq (וּשְׁבַע 'and seven', Num 1:39) is NOT the vet's vowel and stays a numeral.
        if bare.lstrip('ובלכמה') in ('שבע', 'שבעה', 'שבעת') and not bare.endswith('*'):
            core = bare[len(bare) - len(bare.lstrip('ובלכמה')):] if bare.lstrip('ובלכמה') else bare
            st = pw[pw.rfind('ש'):]                                     # the stem with its points: shin, its dots, the vet's vowel
            stem = st.replace('\u05BC', '')                             # the dagesh off
            vet = re.search(r'ב([\u05B0-\u05BB]*)', stem)
            vv = vet.group(1) if vet else ''
            pb = re.sub(r'[֑-ׇ/]', '', raws[i - 1]) if i > 0 else ''
            pb2 = re.sub(r'[֑-ׇ/]', '', raws[i - 2]) if i > 1 else ''
            if '\u05C2' in stem or '\u05BB' in vv or '\u05B4' in vv or pb in ('באר', 'בבאר', 'מבאר', 'לבאר', 'ובאר', 'ובבאר', 'ומבאר') or (pb == 'אתה' and pb2 == 'ויקרא'):
                bare = bare + '*'
        m = _DUAL.match(bare)                                    # (5) the dual noun: 'two days', 'two cubits' — the numeral in the ending
        if m:
            bare = (m.group(1) or '') + m.group(2) + '~'
        # THE NUMBERS WALK 6b (2026-09-11; NUMBERS_WALK.md "Sitting 6b"): (19) THE DUAL "TWICE" — the noun of occurrences in the DUAL carries the
        #     numeral two as the dual unit nouns do: פַּעֲמַיִם 'twice' (a PATACH under the pe; the morphology's own dual tag — Num 20:11 'he struck
        #     the rock twice', Gen 27:36, 41:32, 43:10 the Torah's four; nine in the Tanakh) is emitted with the tilde; פְּעָמִים 'times' (a sheva
        #     under the pe, 47 seats: 'seven times' Num 19:4, Lev 4:6) stays a word after its numeral. Measured on the whole DB at the sitting.
        if bare.lstrip('ובלכ') == 'פעמים' and not bare.endswith('*'):
            st = pw[pw.rfind('פ'):].replace('ּ', '')
            if re.match(r'^פַ', st):
                bare = bare + '~'
        # THE NUMBERS WALK 9b (2026-09-11; NUMBERS_WALK.md "Sitting 9b"): (27) THE FIVE-STEM'S THREE HOMOGRAPHS BY THE POINTS ON THE STEM (the tithe
        #     verb's rule 16 at a second stem): the piel verb וְחִמֵּשׁ 'and let him take a FIFTH' (Gen 41:34 — a HIRIQ under the chet) had read as five;
        #     the passive participle חֲמֻשִׁים 'ARMED' (Exod 13:18; Josh 1:14, 4:12; Judg 7:11 — a QUBUTS under the mem) had read as FIFTY; the noun
        #     חֹמֶשׁ 'a fifth' (Gen 47:26 'to Pharaoh for the fifth part'; the fifth rib of 2 Sam 2:23, 3:27, 4:6, 20:10 — a HOLAM under the chet) had read
        #     as five. The numeral's chet carries a qamats (חָמֵשׁ "five") or a chataf (חֲמִשָּׁה "five"; חֲמִשִּׁים "fifty", a hiriq under the mem). Each starred.
        if bare.lstrip('ובלכמה') in ('חמש', 'חמשים') and not bare.endswith('*'):
            st = pw[pw.rfind('ח'):]
            vc = re.match(r'^ח([ְ-ּ]*)', st).group(1)                                         # the chet's vowel
            mi = st.find('מ')
            vm = re.match(r'^מ([ְ-ּ]*)', st[mi:]).group(1) if mi >= 0 else ''                   # the mem's vowel
            if 'ִ' in vc or 'ֹ' in vc or 'ֻ' in vm:
                bare = bare + '*'
        # THE NUMBERS WALK 15b (2026-09-13; NUMBERS_WALK.md "Sitting 15b"): (29) THE BARE DUAL THOUSAND BY THE POINTS ON THE STEM — אַלְפַּיִם 'two
        #     thousand' carries a SHEVA under the lamed (and a patach with the dagesh in the pe; Num 35:5 x4 'two thousand by the cubit', Josh 3:4
        #     'about two thousand cubits', 1 Sam 13:2, 1 Kgs 7:26, 2 Kgs 18:23, Isa 36:8, Judg 20:45, Josh 7:3 — TWENTY-NINE Tanakh seats measured at
        #     the sitting, twenty-one of them inside compounds that already read right); אֲלָפִים 'thousands' carries a QAMATS under the lamed (146
        #     seats — 'rulers of thousands' Exod 18:21, 'three thousands' Num 1:46, 'sheep and OXEN' Ps 8:8). The dual is emitted with the dual mark
        #     (the tilde of rule 5) so ink_numbers reads it as 2,000 wherever it stands; the plural stays bare and reads as a noun unless a unit
        #     numeral precedes it (the multiplication rule of 1b).
        if bare.lstrip('ובכל') == 'אלפים' and not bare.endswith('*'):
            st = pw[pw.rfind('א'):]
            if re.search(r'ל[ּֽ]*ְ', st):
                bare = bare + '~'
        m = _SUFX.match(bare)                                    # (6) the suffixed numeral: 'the two of them', 'the three of you'
        if m:
            stem = m.group(2) or m.group(4)
            ok = True
            if stem in ('שני', 'שתי'):                            # by the points, as the construct: a sheva under the shin and a tsere after it
                st = pw[pw.rfind('ש'):].replace('\u05C1', '').replace('\u05C2', '').replace('\u05BC', '')
                ok = bool(re.match(r'^ש\u05B0[נת]\u05B5', st))
            if ok:
                bare = (m.group(1) or '') + stem + '#'
        # ---- THE NUMBERS WALK 4b (2026-09-10): rules (12)-(16) ----
        nb1 = re.sub(r'[֑-ׇ/]', '', raws[i + 1]) if i + 1 < len(raws) else ''
        core = bare
        for pre in ('ו', 'ב', 'ל', 'כ'):
            if bare.startswith(pre) and bare[len(pre):] in FRACTIONS:
                core = bare[len(pre):]; break
        if core in FRACTIONS and nb1 in MEASURES and not bare.endswith('*'):      # (12) the fraction before a measure noun
            bare = bare + '%'
        elif _HALF.match(bare) and not bare.endswith('*') and '\u05B2' in pw[pw.rfind('ח'):pw.rfind('ח') + 3]:   # (30) THE HALF OF A NAMED WHOLE (THE DEUTERONOMY WALK 1b, 2026-09-15): the half before any other noun — BY THE POINTS: a hataf-patach under the het (חֲצִי 'half'), not the hiriq of חִצַּי 'my arrows' (Deut 32:23, 32:42 — the diff's find)
            bare = bare + '%'
        elif bare in ('עשרון', 'ועשרון', 'עשרן', 'ועשרן', 'אמה', 'ואמה', 'הין'):    # (13) the unit noun as one — the cubit by its points
            stem_ok = True
            if bare.endswith('אמה'):
                st = pw[pw.rfind('א'):]
                stem_ok = bool(re.match(r'^א\u05B7מ\u05BC', st)) and not st.endswith('\u05BC')
            if stem_ok:
                bare = bare + '@'
        elif bare in ('האחד', 'האחת', 'והאחד', 'והאחת'):                              # (14) the definite one
            # THE NUMBERS WALK 5b (2026-09-10; NUMBERS_WALK.md "Sitting 5b"): (18) THE DEFINITE ONE'S JOIN IS GATED BY THE ACCENT — "the ONE and
            # twentieth day" (Exod 12:18) joins under a darga (conjunctive); "in the ONE curtain, and fifty loops" (Exod 26:5, 36:12 — a segolta)
            # and "from its ONE side, and three branches" (25:32, 37:18 — a zaqef) CLOSE: M-26's read extended to the definite one (the 4b diff
            # had accepted [50, 51] and [6, 3, 4])
            if nb1.startswith('ו') and not nb1.startswith('וה') and nb1[1:] in UNITS and not any(c in _DISJ for c in w):   # the chain joined by the conjunction under a conjunctive accent: the article dropped, the numeral joins
                bare = bare[-3:]
            else:
                bare = bare + '#'
        elif bare.lstrip('ובלכה') == 'שלשים' and not bare.endswith('*'):             # (15) thirty only with a holam under the lamed
            st = pw[pw.rfind('ל'):]
            if '\u05B9' not in st[:4]:
                bare = bare + '*'
        elif bare == 'ששי' and '\u05B5' in pw[:pw.find('ש') + 4]:                   # (15) Sheshai — a tsere under the shin, not the ordinal
            bare = bare + '*'
        elif bare.lstrip('ובלכמה') == 'עשר' and bare.endswith('עשר') and not bare.endswith('*'):   # (16) the tithe verb — a patach under the ayin
            st = pw[pw.rfind('ע'):]
            if '\u05B7' in st[:3] or '\u05B0' in st[:3]:                       # a patach (עַשֵּׂר) or a sheva (לַעְשֵׂר, מַעְשַׂר) under the ayin — the numeral's is a segol, the tenth-day noun's a qamats
                bare = bare + '*'
        out.append(bare)
    # ---- THE NUMBERS WALK 11b (2026-09-12; NUMBERS_WALK.md "Sitting 11b"): (28) THE RATIO "ONE OF THE N" — a unit ONE (אחד / אחת, at most one
    #      non-numeral token after it: the counted noun, "one SOUL of the five hundred") followed by "from" in its three forms — מן, the poetic מני
    #      (Job 9:3, 33:23), the מ-prefix on the numeral itself (מחמש "from five", מאלף "from a thousand") — and a numeral phrase (an article-bearing
    #      chain: החמשים "the fifty", המאות "the hundreds" after the prefixed unit, המאתים "the two hundred", העשרה "the ten"; or the bare word after
    #      the prefix) is THE RATE: the one is emitted as אחד/N% (the parser's fraction mark, Fraction(1, N)) and the denominator's tokens are STARRED
    #      (consumed by the rate, never counted — the register gate's numeral runs skip both marks). Measured at the reading (Num 31:28, 31:30,
    #      31:47; Eccl 7:28; Ezek 45:15 — the second "from" carries the numeral; Neh 11:1) and at the compile (Job's two): eight Bible seats. The
    #      search stops at a numeral with no "from" before it (Josh 3:12 "one man, one man"; Deut 32:30 "one... a thousand") and at the window's
    #      end; "from ONE of your brothers" (Deut 15:7, the prefix on the one itself) and "one of them / of his ribs" (a pronoun, a noun) are left.
    i = 0
    while i < len(out):
        t = out[i]
        if t.rstrip('|') in ('אחד', 'אחת'):
            k, prefixed = None, False
            for j in range(i + 1, min(i + 5, len(out))):
                u = out[j]
                if _bare(u) is not None and not u.endswith(('*', '%', '@')):
                    break                                                                    # a numeral with no "from" before it: no ratio
                if u in ('מן', 'מני') and j + 1 < len(out) and _bare(out[j + 1]) is not None and not out[j + 1].endswith(('*', '%', '@', '#', '~')):
                    k = j + 1; break
                if u.startswith('מ') and len(u) > 1 and _bare(u) is None and _bare(u[1:]) is not None and not u.endswith(('*', '%', '@', '#', '~')):
                    k, prefixed = j, True; break
            if k is not None:
                toks, m = [], k
                while m < len(out):
                    u = out[m]
                    core = u[1:] if (m == k and prefixed) else u
                    if u.endswith(('*', '%', '@', '#', '~', '|')) or _bare(core) is None:
                        break
                    toks.append(_bare(core)); m += 1
                n = ink_numbers(toks) if toks else []
                if len(n) == 1 and isinstance(n[0], int) and n[0] > 1:
                    out[i] = t.rstrip('|') + '/%d%%' % n[0]
                    for x in range(k, m):
                        out[x] = out[x] + '*'
                    i = m
                    continue
        i += 1
    return out


def _bare(w):
    w = w.rstrip('|')                                         # THE NUMBERS WALK 2b: a barred 'one' is the unit one
    for p in ('וה', 'וב', 'ול', 'וכ', 'ו', 'ב', 'ל', 'כ', 'ה'):   # THE NUMBERS WALK 3b: 'וכ' (and about — Num 11:31 וכאמתים); 1b (2026-09-09): the article on each part — Num 3:46 השלשה והשבעים והמאתים ('the three and the seventy and the two hundred')
        if w.startswith(p) and w[len(p):] in UNITS:
            return w[len(p):]
    return w if w in UNITS else None


def ink_numbers(words):
    """the number phrases of a verse, computed from its numeral words: a unit (one to nine) IMMEDIATELY before
    מאת/מאות ('hundred'/'hundreds') MULTIPLIES, every other numeral word ADDS; שתים ('two', feminine) counts; שנים
    counts as 'two' only before עשר ('ten') or ועשרים ('and twenty' — the census's 'two and twenty thousand', Num 3:39),
    else it is 'years'; a YEAR-word (שנה/שנים) keeps the phrase open — the ink writes a number in parts joined by 'and'
    with the noun between (Gen 5:6 חמש שנים ומאת שנה, five years and a hundred years = 105) — while any other word
    closes it (Exod 24:18 ארבעים יום וארבעים לילה, forty days and forty nights = two numbers) (SEQUENTIAL_RUN.md section 4).
    THE CENSUS'S GRAMMAR (THE NUMBERS WALK 1b, 2026-09-09; NUMBERS_WALK.md "Sitting 1b" — measured on every number of
    Num 1:1-4:20, probed by census_probes.py): אלף/אלפים ('thousand'/'thousands') WITHOUT the conjunction multiplies the
    GROUP since the last thousands-word (Num 1:21 ששה וארבעים אלף, six and forty thousand = 46,000; 1:46 שש מאות אלף
    ושלשת אלפים, 603,000; an empty group: אלף = 1,000, אלפים = 2,000 — the dual, Num 35:5); WITH the conjunction, ואלף
    ('and a thousand') ADDS (Num 3:50 five and sixty and three hundred and a thousand = 1,365; Exod 38:25; Num 26:51);
    a numeral word IDENTICAL to the numeral word before it is DISTRIBUTIVE — one number (Num 3:47 חמשת חמשת, 'five,
    five' shekels per skull = 5; Gen 7:2 'seven, seven' = 7); מֵאֵת ('from') arrives as מ-את from verse_words and is no
    numeral (Num 3:49-50, Gen 23:20)."""
    out, add, k, seen, prev_unit, last = [], [], 0, False, 0, None   # k: where the group since the last thousands-word begins
    after_year = False                                             # THE NUMBERS WALK 2b: a phrase held open by a year-word continues only through the conjunction
    for i, w in enumerate(words):
        cut = w.endswith('|'); w = w.rstrip('|')                  # THE NUMBERS WALK 2b: the bar — a disjunctive on 'one' before a bare numeral (M-26)
        # ---- THE NUMBERS WALK 4b (2026-09-10): (12) the fraction of a measure, (13) the unit noun as one ----
        if w.endswith('%'):
            core = w[:-1]
            if core == 'וחצי' and seen and len(add) > k:              # (7) keeps precedence: "a cubit and a half OF THE cubit" continues the numeral
                add.append(0.5); prev_unit = 0; last = None
                continue
            for pre in ('ו', 'ב', 'ל', 'כ'):
                if core.startswith(pre) and core[len(pre):] in FRACTIONS:
                    core = core[len(pre):]; break
            if _HALF.match(core):                                        # (30) THE DEUTERONOMY WALK 1b (2026-09-15): every prefixed half-form reduces to its bare word
                core = 'מחצית' if core.endswith('מחצית') else 'חצי'
            if seen:
                out.append(sum(add))
            if '/' in core:                                              # 11b (28): the ratio אחד/N% from verse_words — "one of the N" = Fraction(1, N)
                out.append(Fraction(1, int(core.split('/')[1])))
            else:
                out.append(FRACTIONS[core])
            add, k, seen, prev_unit, last, after_year = [], 0, False, 0, None, False
            continue
        if w.endswith('@'):
            after_year = False
            if seen:                                                  # after a numeral the noun is the number's unit: it closes, adds nothing
                out.append(sum(add)); add, k, seen, prev_unit, last = [], 0, False, 0, None
                continue
            look = [x.rstrip('|#') for x in words[i + 1:i + 3]]
            if any(_bare(x) in ('אחד', 'אחת') for x in look):         # "a tenth, ONE" — the numeral adjective after the noun counts it
                add, k, seen, prev_unit, last = [], 0, False, 0, None
                continue
            add.append(1); seen = True; prev_unit = 0; last = w        # the unit noun as one; the phrase stays open for "and a half"
            continue
        b = _bare(w)
        if b is not None and after_year and seen and not w.startswith('ו'):   # (only a phrase actually held open — the first diff printed zeros where none was)
            # AFTER A YEAR-WORD ONLY 'AND N' CONTINUES THE NUMBER (Gen 5:6 'five years AND a hundred years'); a bare numeral after it begins a new
            # one — Gen 31:41 'fourteen years, for your TWO daughters', Deut 1:3 'in the fortieth year, in the ELEVENTH month', Lev 25:8 'seven
            # years, SEVEN times' (the diff of 2026-09-10 read verse by verse)
            out.append(sum(add)); add, k, seen, prev_unit, last = [], 0, False, 0, None
        after_year = False
        if b in ('אחד#', 'אחת#'):                                  # (14) 4b: THE DEFINITE ONE — the article rules below do not apply; it counts one and closes
            pass
        elif b is not None and w.startswith('ה') and not w.startswith('וה'):
            # THE ARTICLE ON A NUMERAL counts only at the head of a chain joined by 'and the' (Num 3:46 השלשה והשבעים והמאתים);
            # alone it is a name or a noun — קרית הארבע 'Kiriath-arba' (Gen 35:27), שני השבע 'the years of plenty' (Gen 41:53):
            # the stitcher's marker verification caught both when the article was first admitted (2026-09-09)
            # THE NUMBERS WALK 5b (2026-09-10): (17) THE DEFINITE NUMERAL AT THE HEAD OF A COMPOUND — the article-bearing numeral before plain 'and'
            # + a bare numeral ALSO opens the chain: Num 16:35 החמשים ומאתים ('THE fifty and two hundred' = 250, read [200] since 1b), Exod
            # 38:28 האלף ושבע המאות ('THE thousand and seven THE hundreds...' = 1,775 — 38:25's own number, read [7, 75])
            nxt = words[i + 1].rstrip('|#') if i + 1 < len(words) else ''
            if not ((nxt.startswith('וה') and _bare(nxt) is not None) or (nxt.startswith('ו') and not nxt.startswith('וה') and _bare(nxt) is not None)):
                b = None
        if b is not None and w.startswith('וה') and b not in ('אחד#', 'אחת#'):   # 4b: "and the one" (Lev 14:22) now counts — the definite one
            # 'and the N' counts only INSIDE a chain (after a numeral word): 'and the other' (Gen 42:13, Lev 14:22 והאחד) is no number
            if not (i > 0 and (_bare(words[i - 1]) is not None or words[i - 1] in ('שנה', 'שנת', 'ושנה'))):
                b = None
        if b in ('אלפים', 'מאות') and (w.startswith('ה') or w.startswith('וה')) and not prev_unit:
            # THE NUMBERS WALK 5b (2026-09-10): (17c) THE ARTICLE-BEARING PLURAL UNIT WORD IS A NOUN unless a unit numeral precedes it — 'the captains
            # of THE THOUSANDS and of THE HUNDREDS' (Num 31:54 — read [2100] by the 'and the' chain since 1b; 31:14, 31:48 the same phrase) against
            # (17b) 'seven THE hundreds' (Exod 38:28 — the article on the hundreds-word after a unit MULTIPLIES, the existing hundreds rule)
            b = None
        if b == 'אלפים' and len(add) == k:
            # THE NUMBERS WALK 15b (2026-09-13): (29) THE BARE DUAL THOUSAND — the dual arrives MARKED from verse_words (אלפים~, by the sheva under
            # the lamed) and reads 2,000 wherever it stands (35:5's 'two thousand by the cubit' four times; Josh 3:4's 'about two thousand cubits';
            # 1 Sam 13:2's 'two thousand with Saul'); the UNMARKED plural 'thousands' with no unit numeral before it is a NOUN — 'rulers of thousands'
            # (Exod 18:21), 'sheep and OXEN' (Ps 8:8, read [2000] since 1b through the old rule, which admitted the bare plural before a numeral: no
            # true seat had that shape — every compound dual is marked now). The rule 1b left ('the dual stands alone only before a numeral word;
            # Num 35:5 waits for its own walk') is paid here.
            b = None
        if b is not None and b == 'אלפי' and len(add) == k:
            # THE NUMBERS WALK 7b (2026-09-11): (22) THE CONSTRUCT "THOUSANDS OF" with no numeral before it is a NOUN — 'the myriads of the
            # thousands of Israel' (Num 10:36), 'the thousands of Manasseh' (Deut 33:17); after a unit it multiplies (Exod 32:28 'three thousands of')
            b = None
        if b is not None:
            if w == last:                                            # the distributive doubling — the SAME raw word (3:47 חמשת חמשת; Gen 7:2
                continue                                             # שבעה שבעה); with the conjunction it is two numbers (Lev 26:8 מאה ומאה; Num 26:51 אלף ואלף)
            last = w
            v = UNITS[b]
            if b in ('אלף', 'אלפים', 'אלפי', 'אלפים~'):                  # 7b: the construct 'thousands of' multiplies the group like the plural; 15b: the marked dual
                if w.startswith('ו') and b == 'אלף':                  # 'and a thousand' — an addend
                    add.append(1000)
                elif len(add) == k:                                  # a bare thousand / the dual 'thousands'
                    add.append(2000 if b in ('אלפים', 'אלפים~') else 1000)   # 15b: the marked dual 2,000 wherever it stands (the bare plural never reaches here)
                else:                                                # the group since the last thousands-word, multiplied
                    add = add[:k] + [sum(add[k:]) * 1000]
                k = len(add); prev_unit = 0
            elif b in ('מאת', 'מאות') and prev_unit:
                add[-1] = prev_unit * 100; prev_unit = 0
            else:
                add.append(v); prev_unit = v if 1 <= v <= 9 else 0
            seen = True
            if cut or w.endswith('#'):                               # M-26: the number ends on the disjunctive 'one' (7:13 [1, 130, ...], 7:14 [1, 10]); 3b: a SUFFIXED numeral is a whole phrase — it closes (Exod 26:24 'for the two of them, for the two corners' = [2, 2], not 4)
                out.append(sum(add))
                add, k, seen, prev_unit, last = [], 0, False, 0, None
        elif w in ('שנה', 'שנת', 'ושנה') or w.endswith('שנים*') or w.endswith('שני*'):
            prev_unit = 0; last = None; after_year = True            # the year-word keeps the phrase open (שנים* — 'years' by its points; שני* 'the years of')
        elif w == 'וחצי' and seen and len(add) > k:              # (7) THE HALF (3b): 'and a half' right after a numeral — Exod 25:10 'two cubits and a half' = 2.5
            add.append(0.5); prev_unit = 0; last = None
        else:
            if seen:
                out.append(sum(add))
            add, k, seen, prev_unit, last = [], 0, False, 0, None
    if seen:
        out.append(sum(add))
    return out


def ink_ordinals(words):
    """the ordinals of a verse (the months' names before Exod 12:2, the creation days) — with their ה/ב prefixes.
    THE NUMBERS WALK 6b (2026-09-11; NUMBERS_WALK.md "Sitting 6b"): (20) THE DEFINITE NUMERAL AFTER THE YEAR-CONSTRUCT IS AN ORDINAL YEAR —
    בִּשְׁנַת הָאַרְבָּעִים 'in the year of THE forty' (Num 33:38, Aaron's death-date; the Torah's one seat) = the fortieth year: the article-bearing
    numeral chain right after 'in the year of' / 'the year of' is read by the numbers grammar with its articles off and returned as ONE
    ordinal (1 Kgs 6:1's 'the four hundred and eighty' the same form outside the Torah); the numbers reader leaves it silent (5b's rule 17)."""
    out = []
    i = 0
    while i < len(words):
        w = words[i]
        if w in ('בשנת', 'שנת', 'ובשנת') and i + 1 < len(words) and words[i + 1].startswith('ה') and _bare(words[i + 1]) is not None:
            chain = []
            j = i + 1
            while j < len(words) and _bare(words[j]) is not None and (j == i + 1 or words[j].startswith(('ו', 'ה'))):
                chain.append(words[j].lstrip('ה') if not words[j].startswith('וה') else 'ו' + words[j][2:])
                j += 1
            n = ink_numbers(chain)
            if len(n) == 1:
                out.append(n[0]); i = j; continue
        n = _bare_ord(w)
        if n is not None:
            out.append(n)
        i += 1
    return out


_VREF = re.compile(r'^(Gen|Exod|Lev|Num|Deut)\s+(\d+):(\d+)')   # THE DEUTERONOMY WALK 1b (2026-09-15): the fifth book joins the tape's books (assert_ink and the slot stamp read Deuteronomy's verses); THE TENT sitting 2 (2026-09-09): the fourth
def slot_of(book, ch, vs):
    """O9 OPEN-5 (2026-09-08; CLOCK.md 12e): the verse's own day-word, by the registry's day_slots table (the words and
    two-word phrases as the verse carries them, points stripped) — exactly ONE slot's word present, else None (a verse that
    names two slots — Gen 1:5's evening and morning, Exod 16:12's — is stamped nothing, said so in the stitcher's census)"""
    ws = [w.rstrip('*~@^%') for w in verse_words(book, ch, vs)]   # THE DEUTERONOMY WALK 1b (2026-09-15): the parser's marks stripped before the slot match — rule 30's fraction mark on 'in the half of' (Exod 12:29 בחצי%, 'at half of the night') broke the midnight phrase's second hit and stamped the plague line 'night' at the first stitch (13 -> 14 read at the first tape run); the marks are the number parser's annotations, not the ink's words
    hits = []
    for row in WE.CAL_SLOTS:
        if any(x in ws for x in row.get('words', [])) or any(all(x in ws for x in ph) for ph in row.get('phrases', [])):
            hits.append(row['name'])
    return hits[0] if len(hits) == 1 else None


_INK_CHECKS = []


def assert_ink(verse, numbers, ordinals=None, words=None):
    """the run-time re-parse: the marker's literal numbers (and month ordinals) must equal the ink's own; `words` (O1,
    2026-09-07) names bare words the verse must carry — Exod 32:30's ממחרת ('on the morrow'), the marker's own day-word"""
    m = _VREF.match(verse)
    ws = verse_words(m.group(1), int(m.group(2)), int(m.group(3)))
    got = ink_numbers(ws)
    ok = got == list(numbers) and (ordinals is None or ink_ordinals(ws) == list(ordinals)) and (words is None or all(x in ws for x in words))
    _INK_CHECKS.append((verse, ok))
    if not ok:
        raise SystemExit('INK MISMATCH at %s: the marker says %r%s%s, the verse parses %r%s' % (
            verse, numbers, '' if ordinals is None else ' ordinals %r' % (ordinals,), '' if words is None else ' words %r' % (words,),
            got, '' if ordinals is None else ' ordinals %r' % (ink_ordinals(ws),)))


def next_date(w, m, dom):
    """the next (ordinal month m, day dom) of the world's own era at or after the counter"""
    y = w.clock.date_in(w.clock.epoch)[0]
    d = w.clock.day_in(w.clock.epoch, y, m, dom)
    return d if d >= w.clock.day else w.clock.day_in(w.clock.epoch, y + 1, m, dom)


def yr(w, day):
    """the world's own (creation) year of a day"""
    return w.clock.calendar.year(day)


def year_day(w, y):
    """the first day of the world's year y — where a birth or an age-at-event is MODELED within its year (the year
    grain is the ink's; the day within it is modeled at the year's first day, Rosh Hashanah 10b:10)"""
    return w.clock.day_in(w.clock.epoch, y, 1, 1)


def cal_day(w, y, m, dom):
    """a day by the CALENDAR'S OWN month numbering — the ink's (Exod 12:2 'the first month' = Nisan; Tishrei the seventh;
    the thirteenth after Adar): the right address for a post-12:2 month name in ANY creation year, leap or not. The era
    view's ORDINAL months serve the pre-12:2 ink (Gen 7:11's 'second month' counted from Tishrei) and the exodus era's
    own count from Nisan. O1's sojourn fork caught the difference: the descent-literal world's exodus year is a
    thirteen-month year, and 'the ordinal seventh from Tishrei' there is Adar II, not Nisan"""
    return w.clock.calendar.day_of(y, m, dom)


def birth_day(w, y, who):
    """the day a birth is placed within its year (O1, 2026-09-07; SEQUENTIAL_RUN.md section 12 d): the shelf's row where
    it gives one — isaac_birth_date (on Passover Isaac was born: the fifteenth of the first month, Rosh Hashanah 10b:10
    and 11a:2, both arms), patriarch_birth_month (Abraham, Jacob and Esau in Tishrei, the seventh month, Rabbi Eliezer;
    the day within the month modeled at the first) — else the year's first day, the model of section 4. The months are
    the calendar's own numbering (cal_day)"""
    P = WE.CAL_PARAMS
    if who == 'isaac':
        r = P['isaac_birth_date']['value']
